; Recompiled from C to 6502 Assembly
; NES ROM for Super Mario Bros
; Original: Disassembled and decompiled, now recompiled

; ===== ROM HEADER (iNES Format) =====
; This will be generated by the NES packer

; ===== PRG-ROM CODE ($8000-$FFFF) =====

; ===== DATA SECTION =====
; PPU_CTRL = $2000
; PPU_MASK = $2001
; PPU_STATUS = $2002
; OAM_ADDR = $2003
; OAM_DATA = $2004
; PPU_SCROLL = $2005
; PPU_ADDR = $2006
; PPU_DATA = $2007
; SQ1_VOL = $4000
; SQ1_SWEEP = $4001
; SQ1_LO = $4002
; SQ1_HI = $4003
; SQ2_VOL = $4004
; DPCM_DAC = $4011
; APU_ENABLE = $4015
; OAM_DMA = $4014
; JOY1 = $4016
; JOY2 = $4017

; ===== CODE SECTION =====

$8000:
    SEI               ; Disable interrupts
    CLD               ; Clear decimal mode
    LDA #$10          ; Load PPU control value
    STA $2000         ; Set PPU_CTRL
    LDX #$FF          ; Load X with 255
    TXS               ; Set stack pointer

; Wait for PPU to stabilize
    LDA $2002         ; Read PPU_STATUS
    BPL $-3           ; Branch if not in VBlank
    LDA $2002         ; Read again
    BPL $-3           ; Branch if not in VBlank

; Initialize APU
    LDA #$0F          ; Enable all APU channels
    STA $4015         ; Write to APU_ENABLE

; Enable rendering
    LDA #$06          ; PPU_MASK value
    STA $2001         ; Enable backgrounds and sprites

; Main game loop
$8057:
    JMP $8057         ; Infinite loop (placeholder)

; Game data tables and padding
    .byte $00, $A4, $00, $00  ; Level data markers

